  // ─── HTML Blocks (used with data-i18n-html) ──────────────────────
  'help.install_app_html':
    'MUSIXQUARE నచ్చిందా? దీన్ని యాప్‌గా ఇన్‌స్టాల్ చేసుకోవచ్చు.<ul class="help-list"><li><strong>iOS:</strong> షేర్ → హోమ్ స్క్రీన్‌కు జోడించు</li><li><strong>Android:</strong> మెనూ → యాప్‌ను ఇన్‌స్టాల్ చేయి</li><li><strong>Windows:</strong> అడ్రస్ బార్‌లోని ఇన్‌స్టాల్ ఐకాన్</li><li><strong>macOS:</strong> షేర్ → Dockకు జోడించు</li></ul>',
  'help.local_recommended_html':
    'ఒకే నెట్‌వర్క్‌లో ఆడియో షేరింగ్ అత్యంత స్థిరంగా ఉంటుంది.<ul class="help-list"><li>రిమోట్‌గా చేరినవారు కూడా అవే ఫీచర్లను ఉపయోగించవచ్చు.</li><li>రిమోట్‌గా చేరినవారి డేటా Cloudflare మార్గాల్లో వెళ్తుంది, కాబట్టి నెట్‌వర్క్ పరిస్థితులను బట్టి ఆలస్యం పెరగవచ్చు లేదా ఆడియో అందకపోవచ్చు.</li><li>VPN లేదా పరిమితం చేసిన నెట్‌వర్క్ కనెక్షన్‌ను అస్థిరంగా చేయవచ్చు.</li></ul>',
  'setup.how_to_connect_html':
    'కనెక్ట్ కావడానికి హోస్ట్ ఇచ్చిన <strong>6 అంకెల కోడ్‌ను</strong> నమోదు చేయండి.<ul class="help-list"><li><strong>హోస్ట్:</strong> “గదిని సృష్టించు” → కోడ్ చూడండి</li><li><strong>పాల్గొనేవారు:</strong> “గదిలో చేరు” → కోడ్ నమోదు చేయండి</li><li>హోస్ట్‌తో కలిపి గరిష్ఠంగా <strong>100 పరికరాలు</strong> కనెక్ట్ కావచ్చు.</li></ul>',
  'player.play_speakers_html':
    'ప్రతి ఒక్కరూ ఒక <strong>పాత్రను (అవుట్‌పుట్ ఛానెల్)</strong> ఎంచుకుంటారు.<ul class="help-list"><li><strong>సెంటర్:</strong> స్టీరియో (డిఫాల్ట్) అవుట్‌పుట్</li><li><strong>ఎడమ (Left):</strong> <bdi dir="ltr">L</bdi> ఛానెల్ అవుట్‌పుట్</li><li><strong>కుడి (Right):</strong> <bdi dir="ltr">R</bdi> ఛానెల్ అవుట్‌పుట్</li><li><strong>సబ్‌వూఫర్:</strong> తక్కువ ఫ్రీక్వెన్సీ మిక్స్ అవుట్‌పుట్</li></ul><strong>సెట్టింగ్‌లలో</strong> పాత్రలను ఎప్పుడైనా మార్చవచ్చు.',
  'player.play_media_action_html':
    'హోస్ట్‌కు 3 ఎంపికలు ఉన్నాయి.<ul class="help-list"><li><strong>లోకల్ ఫైల్ లోడ్:</strong> మీ పరికరం నుండి సంగీతాన్ని ఎంచుకోండి. ఖచ్చితమైన సింక్‌కు మద్దతు ఉంది</li><li><strong>కలిసి YouTube:</strong> వీడియోలు, ప్లేలిస్ట్‌లకు మద్దతు ఉంది. ఛానెల్ విభజన లేదా ఆడియో ఎఫెక్ట్‌లు ఉండవు</li><li><strong>సిస్టమ్ ఆడియో షేరింగ్:</strong> హోస్ట్ కంప్యూటర్‌లో Chromium ఆధారిత బ్రౌజర్‌ను ఉపయోగించినప్పుడు అందుబాటులో ఉంటుంది</li></ul>',
  'help.need_help_html':
    '<ul class="help-list"><li><strong>కోడ్ నమోదు చేసినా కనెక్ట్ కావడం లేదా:</strong> కోడ్‌ను తనిఖీ చేసి కాసేపట్లో మళ్లీ ప్రయత్నించండి. కంపెనీ, పాఠశాల లేదా VPN నెట్‌వర్క్ కనెక్షన్‌ను పరిమితం చేయవచ్చు.</li><li><strong>కనెక్షన్ అస్థిరంగా ఉందా:</strong> లోకల్‌గా చేరినవారు రౌటర్‌కు దగ్గరగా ఉండండి; రిమోట్‌గా చేరినవారు స్థిరమైన ఇంటర్నెట్ కనెక్షన్‌ను ఉపయోగించండి.</li><li><strong>ఇతర సమస్యలు:</strong> నెట్‌వర్క్ స్థితిని తనిఖీ చేసి అన్ని పరికరాల్లో యాప్‌ను రీస్టార్ట్ చేయండి. ప్రశ్నలు ఉంటే <a href="/faq" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:underline">FAQ</a> చూడండి లేదా కింద ఉన్న ఈమెయిల్ ద్వారా సంప్రదించండి.</li></ul>',
